var json = JSON.parse(result);
var content = json.data[0].content;
if(content && content.startsWith('https://')) {
    // 如果是视频链接
    if(book.durChapterIndex == chapter.index) {
        java.startBrowser(content.replace(/\\/g, ''), chapter.title);
        java.toast('正在加载视频\n视频加载较慢，请耐心等待');
    }
    result = '【刷新正文】播放\n✅直链:\n' + content;
} else {
    result = content;
}
