@js:
(function() {
    var sourceVal = '全部';
    try {
        var userSource = source.getVariable();
        if (userSource != null && String(userSource).length > 0) {
            sourceVal = userSource;
        }
    } catch (e) {
        java.log('获取用户来源失败，使用默认值');
    }
    return getHost() + '/search?q={{key}}&source=' + encodeURIComponent(sourceVal);
})();
